for (const w of K.walls) {
  const full = w.sw * 0.84, len = full * K.ease.out(K.t.barT * 1.2);
  const x0 = w.cx - full / 2, y = K.h * 0.74;
  c.fillStyle = K.field; K.rect(c, x0, y, full, K.v.alt);
  c.fillStyle = K.ink;   K.rect(c, x0, y, len, K.v.alt);
  const n = String((K.t.beat % 4) + 1), cell = K.v.cell;
  c.fillStyle = K.ink;
  K.bText(c, n, w.cx - K.bW(n, cell) / 2, K.h * 0.12, cell);
}
K.glitch(c, 0.3, 5);
